const float border_width = .01; // proportion of column width
const float res = 64.; // in width
const float num_cols = 3.;
const float scroll_speed = .03; // number of full width scrolls per second

const vec2[] inter_dirs = vec2[](
    vec2(.001, -1.),
    vec2(1., .001),
    vec2(0., 1.),
    vec2(-1., 0.)
);
const vec2[] point_dirs = vec2[](
    vec2(-1., 1.),
    vec2(1., 1.),
    vec2(1., -1.),
    vec2(-1., -1.)
);

vec3 lerp(vec3 a, vec3 b, float t) {
    return a + (b-a)*t;
}

float compareCols(vec3 a, vec3 b) {
    return (abs(a.x-b.x) + abs(a.y-b.y) + abs(a.z-b.z)) / 3.;
}

float dot_self(vec3 u) {
    return dot(u, u);
}

// returns vec4(vec2(pix pos), vec2(pos within pix))
vec4 getPixel(vec2 uv, vec2 gridRes) {
    vec2 pos = uv *= gridRes;
    return vec4(floor(pos), mod(pos, 1.));
}

vec3 getPixColor(vec2 pixel, vec2 gridRes) {
    // prevent interpolation issues
    ivec2 texCoord = ivec2(pixel / gridRes * iChannelResolution[0].xy);

    // use procedural test image
    //return mod((pixel.x + pixel.y*.3) * .25, 2.) < 1. ? vec3(0., 0., 0.) : vec3(1., 1., 1.);

    // use iChannel0
    return texelFetch(iChannel0, texCoord, 0).rgb;
}

// no smoothing
vec3 method0(vec2 uv, vec2 gridRes) {
    return getPixColor(getPixel(uv, gridRes).xy, gridRes);
}

// lerp
vec3 method1(vec2 uv, vec2 gridRes) {
    vec4 pixel = getPixel(uv, gridRes);
    vec2 pixPos = pixel.xy;
    vec2 t = pixel.zw;

    vec3 nw = getPixColor(pixPos, gridRes);
    vec3 ne = getPixColor(pixPos + vec2(1., 0.), gridRes);
    vec3 sw = getPixColor(pixPos + vec2(0., 1.), gridRes);
    vec3 se = getPixColor(pixPos + vec2(1., 1.), gridRes);

    return lerp(lerp(nw, ne, t.x), lerp(sw, se, t.x), t.y);
}

// median
vec3 method2(vec2 uv, vec2 gridRes) {
    vec3 average = method1(uv, gridRes);

    vec2 pixPos = getPixel(uv, gridRes).xy;

    vec3 nw = getPixColor(pixPos, gridRes);
    vec3 ne = getPixColor(pixPos + vec2(1., 0.), gridRes);
    vec3 sw = getPixColor(pixPos + vec2(0., 1.), gridRes);
    vec3 se = getPixColor(pixPos + vec2(1., 1.), gridRes);

    float nw_d = dot_self(nw-average);
    float ne_d = dot_self(ne-average);
    float sw_d = dot_self(sw-average);
    float se_d = dot_self(se-average);

    if (nw_d < ne_d) {
        if (nw_d < sw_d)
            return nw_d < se_d ? nw : se;
        return sw_d < se_d ? sw : se;
    }
    if (ne_d < sw_d)
        return ne_d < se_d ? ne : se;
    return sw_d < se_d ? sw : se;
}

// custom interpolation test
vec3 method3(vec2 uv, vec2 gridRes) {
    vec4 pixel = getPixel(uv, gridRes);
    vec2 pixPos = pixel.xy;
    vec2 modPos = pixel.zw;
    //modPos = (3. - 2. * modPos) * modPos * modPos;

    vec3[] colors = vec3[](
        getPixColor(pixPos, gridRes), // nw
        getPixColor(pixPos + vec2(1., 0.), gridRes), // ne
        getPixColor(pixPos + vec2(1., 1.), gridRes), // se
        getPixColor(pixPos + vec2(0., 1.), gridRes) // sw
    );

    // find the direction of the biggest changes in color (edges)
    vec2 controlPoint = vec2(0., 0.);
    for (int i = 0; i < 4; i++)
        controlPoint += inter_dirs[i] * compareCols(colors[i], colors[(i + 1) & 3]);

    float angle = atan(controlPoint.y, controlPoint.x);
    float ca = cos(angle), sa = sin(angle);
    vec2 angle_vec = vec2(ca, sa);
    vec2 line_vec = vec2(-sa, ca);

    // find the colors on both sides of that line
    vec3 col_a = vec3(0., 0., 0.), col_b = vec3(0., 0., 0.);
    for (int i = 0; i < 4; i++) {
        float dot_ = dot(line_vec, point_dirs[i]);
        if (dot_ > 0.) col_a += colors[i] * (dot_ * dot_);
        else col_b += colors[i] * (dot_ * dot_);
    }

    // find where the transition should be
    vec3 average_col = (colors[0] + colors[1] + colors[2] + colors[3]) * .25;
    float dist_a = compareCols(col_a, average_col);
    float dist_b = compareCols(col_b, average_col);
    float threshold = (.707*dist_b/dist_a-.707) / (1.+dist_b/dist_a);

    float t = dot(modPos - vec2(.5, .5), angle_vec);
    return t > threshold ? col_b : col_a;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 gridRes = vec2(res, iResolution.y/iResolution.x * res);

    vec2 uv = fragCoord/iResolution.xy;

    // scroll
    float scroll_x = mod(uv.x + iTime * scroll_speed, 1.);

    // draw lines
    if (mod(scroll_x * num_cols + border_width/2., 1.) < border_width) {
        fragColor = vec4(0., 0., 0., 1.);
        return;
    }

    // choose interpolation method
    int index = int(scroll_x * num_cols);
    switch(index) {
        case 1:
            fragColor = vec4(method1(uv, gridRes), 1.);
            return;
        case 2:
            fragColor = vec4(method2(uv, gridRes), 1.);
            return;
    }

    fragColor = vec4(method0(uv, gridRes), 1.);
}
